        messages.append(format_tool_result(call.id, result))
return "The operation reached its execution limit. Please narrow the request."

import math

def safe_calculate(operation: str, a: float, b: float) -> dict:
    if operation not in {"add", "subtract", "multiply", "divide"}:
        raise ValueError("Unsupported operation")
    if not all(isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v) for v in (a, b)):
        raise ValueError("Operands must be finite numbers")
    if operation == "add": result = a + b
    elif operation == "subtract": result = a - b
    elif operation == "multiply": result = a * b
    else:
        if b == 0: raise ValueError("Division by zero")
        result = a / b
    if not math.isfinite(result): raise ValueError("Result is not finite")
    return {"operation": operation, "result": result}

WEATHER_DATA = {
    "cuttack": {"temperature_c": 31, "condition": "cloudy"},
    "bhubaneswar": {"temperature_c": 32, "condition": "sunny"}
}

def get_weather(city: str) -> dict:
    if not isinstance(city, str) or not city.strip():
        raise ValueError("A city is required")
    key = city.strip().lower()
    if key not in WEATHER_DATA:
        return {"found": False, "city": city}
    return {"found": True, "city": city, **WEATHER_DATA[key]}

print(get_weather("Cuttack"))

